let MAM = null;
/**
 * The PanTHERIA records: {name, order, troph (1 herbivore, 2 omnivore, 3 carnivore, 0 unknown), m (adult mass, g),
 * b (BMR, mL O2/h), bm (mass of the animals whose BMR was measured, g), L (maximum longevity, months), G (gestation,
 * days), S (age at sexual maturity, days), D (population density, per km²), H (home range, ha)}; missing = null.
 */
export function mammals() {
  if (MAM) return MAM;
  const dec = (s) => (s === '__' ? null : 10 ** ((parseInt(s, 36) - 400) / 100));
  MAM = MAMMAL_DATA.split(';').map((rec) => {
    const k = rec.indexOf('|'), f = rec.slice(k + 1), x = [];
    for (let i = 0; i < 8; i++) x.push(dec(f.slice(2 + 2 * i, 4 + 2 * i)));
    const name = rec.slice(0, k);
    // One BMR entry is about 1000× too high (14 800 mL O2/h for the 14 g feathertail glider): dropped.
    if (name === 'Acrobates pygmaeus') x[1] = x[2] = null;
    return { name, order: ORDERS[OC.indexOf(f[0])], troph: +f[1], m: x[0], b: x[1], bm: x[2], L: x[3], G: x[4], S: x[5], D: x[6], H: x[7] };
  });
  return MAM;
}
/** BMR of a record in watts. */
export const bmrW = (r) => (r.b * J_PER_ML_O2) / 3600;

/** Colour groups for mammal orders (same everywhere in the chapter). */
export const GROUPS = [
  ['rodents', 'purple', ['Rodentia']],
  ['bats', 'teal', ['Chiroptera']],
  ['shrews, moles, hedgehogs, tenrecs', 'orange', ['Soricomorpha', 'Erinaceomorpha', 'Afrosoricida', 'Macroscelidea', 'Scandentia']],
  ['primates', 'gold', ['Primates']],
  ['carnivores', 'red', ['Carnivora']],
  ['hoofed mammals and whales', 'green', ['Artiodactyla', 'Perissodactyla', 'Cetacea', 'Proboscidea', 'Hyracoidea', 'Sirenia', 'Tubulidentata']],
  ['marsupials and monotremes', 'pink', ['Didelphimorphia', 'Diprotodontia', 'Dasyuromorphia', 'Peramelemorphia', 'Microbiotheria', 'Notoryctemorphia', 'Monotremata']],
  ['others', 'muted', []],
];
const GI = new Map(); GROUPS.forEach(([, , os], i) => os.forEach((o) => GI.set(o, i)));
export const groupOf = (r) => GI.get(r.order) ?? GROUPS.length - 1;
/** Legend entries for the order groups that occur in recs. */
export function groupLegend(recs) {
  const seen = new Set(recs.map(groupOf));
  return GROUPS.map(([lab, col], i) => (seen.has(i) ? [col, lab, { dot: true }] : null)).filter(Boolean);
}
/**
 * Scatter recs on a stage, coloured by order group; fx, fy give the coordinates (null = skip).
 * Returns hit records [{X, Y, r, x, y}] in pixels for hoverPick.
 */
export function scatterGroups(s, recs, fx, fy, o = {}) {
  const buckets = GROUPS.map(() => []), hits = [];
  for (const r of recs) {
    const x = fx(r), y = fy(r);
    if (!(x > 0 || !s.lx) || !(y > 0 || !s.ly) || !isFinite(x) || !isFinite(y)) continue;
    buckets[groupOf(r)].push([x, y]); hits.push({ X: s.X(x), Y: s.Y(y), r, x, y });
  }
  buckets.forEach((pts, i) => { if (pts.length) s.dots(pts, { r: o.r ?? 2.6, color: GROUPS[i][1], alpha: o.alpha ?? 0.72 }); });
  return hits;
}
/** Nearest hit to the mouse within tol pixels (or null). */
export function hoverPick(s, hits, tol = 9) {
  const p = s.pointer; if (!p || !p.inside) return null;
  let best = null, bd = tol * tol;
  for (const h of hits) { const d = (h.X - p.px) ** 2 + (h.Y - p.py) ** 2; if (d < bd) { bd = d; best = h; } }
  return best;
}
/** First match of a binomial among records. */
export const find = (recs, name) => recs.find((r) => r.name === name) || null;

/**
 * Least-squares line through (log10 x, log10 y): {n, slope, intercept, r2, se, lo, hi (95% CI of the slope), a (=10^intercept),
 * f(x) = a x^slope}. M = v.M.
 */
export function logFit(M, xs, ys) {
  const lx = xs.map(Math.log10), ly = ys.map(Math.log10), n = lx.length;
  if (n < 3) return null;
  const R = M.linreg(lx, ly), t = n > 30 ? 1.96 + 2.4 / (n - 2) : M.dist.studentT(n - 2).quantile(0.975);
  const a = 10 ** R.intercept;
  return { n, slope: R.slope, intercept: R.intercept, r2: R.r2, se: R.seSlope, lo: R.slope - t * R.seSlope, hi: R.slope + t * R.seSlope, a, sigma: R.sigma, f: (x) => a * x ** R.slope };
}
/** Best intercept for a fixed slope b in log–log space, and the residual sum of squares: {a, ssr, f}. */
export function fixedSlope(xs, ys, b) {
  const n = xs.length; let s = 0;
  for (let i = 0; i < n; i++) s += Math.log10(ys[i]) - b * Math.log10(xs[i]);
  const c = s / n; let ssr = 0;
  for (let i = 0; i < n; i++) ssr += (Math.log10(ys[i]) - b * Math.log10(xs[i]) - c) ** 2;
  return { a: 10 ** c, ssr, f: (x) => 10 ** c * x ** b };
}
/** "1.23" with a real minus sign. */
export const fx = (x, d = 2) => (x < 0 ? '−' : '') + Math.abs(x).toFixed(d);
/** Pretty mass in grams: "8 g", "3.2 kg", "4.1 t". */
export function massTxt(g) {
  if (g < 1000) return `${g < 10 ? g.toFixed(1) : Math.round(g)} g`;
  const kg = g / 1000; if (kg < 1000) return `${kg < 10 ? kg.toFixed(1) : Math.round(kg)} kg`;
  const t = kg / 1000; return `${t < 10 ? t.toFixed(1) : Math.round(t)} t`;
}

